// Live values — the three channels you control and the score the iframe wrote.
const val = (k) => ({ value: nb.get(k), type: typeof nb.get(k) });
return {
  r: val('r'), g: val('g'), b: val('b'),   // all numbers, 0..255
  match_pct: nb.get('match_pct'),           // written back by the HTML cell
  target_seed: nb.get('target_seed'),       // increments on New target
};
